import itertools
def ordered(coins, x):
    w = [1] + [0] * x
    for s in range(1, x + 1): w[s] = sum(w[s - c] for c in coins if c <= s)
    return w
def unordered(coins, x):
    w = [1] + [0] * x
    for c in coins:
        for s in range(c, x + 1): w[s] += w[s - c]
    return w
def slow_ordered(coins, x): return sum(1 for L in range(1, x + 1) for t in itertools.product(coins, repeat=L) if sum(t) == x)
def slow_unordered(coins, x): return sum(1 for L in range(1, x + 1) for t in itertools.combinations_with_replacement(coins, L) if sum(t) == x)
result = slow_unordered((2, 3, 5), 9)

